old = sys.modules.get('phoenix_topo_preview')
if old is not None:
    try:
        old.unload_plugin()
    except Exception:
        pass
for n in ('phoenix_topo_preview', 'phoenix_topo_core', 'phoenixTopoPreview'):
    sys.modules.pop(n, None)
importlib.invalidate_caches()
import phoenix_topo_preview
